gaF_(){return"Quieres empezar ma\xf1ana sabiendo qu\xe9 hacer."},
gaES(){return"Escribe lo de ma\xf1ana"},
gaER(){return"Una cosa por l\xednea, sin ordenar. Tambi\xe9n puedes dictarlo."},
gaEU(){return"P\xe1salo a Prioridades"},
gaET(){return"Lo guardamos para que ma\xf1ana lo encuentres ah\xed."},
gaEW(){return"Respira lento"},
